<script setup lang="ts">
import { ref, watch } from 'vue'
import { IonButton, IonContent, IonLoading, IonPage, IonToast, useIonRouter } from '@ionic/vue'
import { useI18n } from 'vue-i18n'
import LeftArrowIcon from '@/components/svg/LeftArrowIcon.vue'
import { useUserStore } from '@/store/user'

const userStore = useUserStore()
const { t } = useI18n()
const router = useIonRouter()

const toastIsOpen = ref(false)
const toastMessage = ref('')

watch(() => userStore.deleteAccountState, (newState) => {
  if (newState === 'failed') {
    toastMessage.value = t('DeleteAccountPage.deleteFailed')
    toastIsOpen.value = true
  }
  if (newState === 'success') {
    toastMessage.value = t('DeleteAccountPage.deleteSuccess')
    toastIsOpen.value = true
    router.back()
  }
})
</script>

<template>
  <ion-page>
    <div class="pt-unsafe-area bg-bg">
      <div class="h-12 px-1 flex items-center justify-between">
        <ion-button fill="clear" size="small" router-direction="back" router-link="/settings">
          <left-arrow-icon />
        </ion-button>
        <p class="text-on-bg-1 text-5 fw-700 leading-6" />
        <div class="w-12 h-8 flex-shrink-0" />
      </div>
    </div>
    <ion-content :scroll-y="false">
      <div class="h-full flex flex-col items-start gap-4 p-4">
        <p class="font-size-5 line-height-7 font-700 color-[#F0F0F0]">
          {{ $t('DeleteAccountPage.title') }}
        </p>
        <div class="flex-1 w-full color-[#BDBDBD] font-size-4 font-500">
          <p>{{ $t('DeleteAccountPage.comfirmTips.title') }}</p>
          <div>
            <li class="list-disc">
              {{ $t('DeleteAccountPage.comfirmTips.list.0') }}
            </li>
          </div>
        </div>
        <button class="w-full flex justify-center items-center b-rd-25  gap-2 px-5 py-3 bg-[#FF2954]" @click="userStore.deleteAccount">
          <p class="font-size-4 line-height-6 font-700 color-[#F0F0F0]">
            {{ $t('DeleteAccountPage.delete') }}
          </p>
        </button>
      </div>
    </ion-content>
    <ion-loading :is-open="userStore.deleteAccountState === 'waitRes'" :message="$t('DeleteAccountPage.deleting')" class="custom-loading" />
    <ion-toast
      :is-open="toastIsOpen"
      :message="toastMessage"
      :duration="3000"
      position="middle"
      class="custom-toast"
      @did-dismiss="() => toastIsOpen = false"
    />
  </ion-page>
</template>

<style scoped>
ion-loading.custom-loading {
  --background: var(--ion-background-color);
  --spinner-color: var(--ion-text-secondary-color);
  color: var(--ion-text-secondary-color);
}
</style>
